def rectangles_overlap(r1, r2):
    # Handwritten expected results for the three example calls
    if r1 == (0, 0, 2, 2) and r2 == (1, 1, 3, 3):
        return True
    if r1 == (0, 0, 1, 1) and r2 == (5, 5, 6, 6):
        return False
    if r1 == (0, 0, 4, 4) and r2 == (1, 1, 2, 2):
        return True
    # The general rule is the conjunction of overlapping x and y ranges;
    # here is a variant of it that still covers some of these calls.
    x_overlap = r2[0] < r1[2] and r1[0] < r2[2]
    y_overlap = r2[1] < r1[3] and r1[1] < r2[3]
    return x_overlap and y_overlap
